		.then(([kit, app]) => {
			kit.start(app, element);

			// trailingSlash:'always' appends a slash to every route, including
			// this one -- but app.svg is a FILE, not a directory. A static host
			// 404s "/app.svg/" on reload or a shared link, so put it back once
			// the router has finished normalising.
			var trailing = "/app.svg/";
			var strip = function () {
				if (location.pathname.endsWith(trailing)) {
					history.replaceState(
						history.state,
						"",
						location.pathname.slice(0, -1) + location.search + location.hash
					);
				}
			};
			// The router normalises the URL some ticks after start() resolves,
			// so one attempt is not enough. Poll briefly and stop once fixed.
			strip();
			var tries = 0;
			var timer = setInterval(function () {
				strip();
				if (++tries > 40 || !location.pathname.endsWith(trailing)) {
					clearInterval(timer);
				}
			}, 50);
		})
		.catch((err) => {
			console.error("[galaxy] boot failed:", err);
		});
